 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    runs = []
    for row_idx in (0, h - 1):
        c = 0
        while c < w:
            if grid[row_idx][c] == 0:
                c += 1
                continue
            start = c
            seq = []
            while c < w and grid[row_idx][c] != 0:
                seq.append(grid[row_idx][c])
                c += 1
            runs.append((seq, start))
    # For every isolated interior marker, extend its border string through that marker.
    for r in range(1, h - 1):
        for c, value in enumerate(grid[r]):
            if value == 0:
                continue
            choices = [(seq, start) for seq, start in runs if value in seq]
            if not choices:
                continue
            # Border templates are distinct in the demonstrations; choose the shortest matching run if needed.
            seq, _ = min(choices, key=lambda item: len(item[0]))
            index = seq.index(value)
            left = c - index
            for i, color in enumerate(seq):
                col = left + i
                if 0 <= col < w:
                    out[r][col] = color
    return out
